#include <bits/stdc++.h>
using namespace std;

int main(void){
	string s;
	int n,cur=0;
	cin>>s;
	n=s.size();
	while(cur<(n-1)){
		if((s[cur]=='W')&&(s[cur+1]=='A')){
			s[cur]='A';
			s[cur+1]='C';
			if(cur>0)cur--;
		}
		else cur++;
	}
	cout<<s<<endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(void){
	string s;
	cin>>s;
	int n=s.size();
	for(int i=n-2;i>=0;i--){
		if((s[i]=='W')&&(s[i+1]=='A')){
			s[i]='A';
			s[i+1]='C';
		}
	}
	cout<<s<<endl;
	return 0;
}
